from typing import List

class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        positions = []
        for i, num in enumerate(nums):
            if num == x:
                positions.append(i)
        result = []
        for q in queries:
            if q <= len(positions):
                result.append(positions[q-1])
            else:
                result.append(-1)
        return result

